-- The knowledge base's index: everything Elysium searches is one document per source, split into
-- passages, each with a full-text vector for exact words and an embedding for meaning. Postgres
-- holds all of it, with pgvector for the embeddings, so there is no search cluster. See
-- docs/knowledge.md.

-- pgvector is not a trusted extension, so creating it takes a superuser. Every stack migrates as
-- POSTGRES_USER, the cluster's bootstrap superuser. See docs/database.md.
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE knowledge_documents (
    -- Generated by the API (UUIDv7).
    id UUID PRIMARY KEY,
    -- What the search's source filter calls it: a timeline record's kind, such as `slack` or
    -- `meeting`, and `learning` or `company_doc` once those are indexed.
    source TEXT NOT NULL CHECK (source ~ '^[a-z][a-z0-9_]{0,31}$'),
    -- The one thing it was made from. Each kind of source is a column of its own rather than a
    -- kind and an id, so Postgres removes a document with its source and refuses one for a source
    -- that is already gone. Unique, so indexing the same source again upserts its one document. A
    -- new kind of source adds its column here and to knowledge_documents_one_source.
    timeline_record_id UUID UNIQUE REFERENCES timeline_records (id) ON DELETE CASCADE,
    -- How a citation names it and links to it, as its source does.
    title TEXT NOT NULL DEFAULT '' CHECK (char_length(title) <= 2048),
    url TEXT CHECK (char_length(url) <= 4096),
    -- When what it says was said, for the date filter.
    occurred_at TIMESTAMPTZ NOT NULL,
    -- The hex SHA-256 of the text it was indexed from, so indexing an unchanged source again
    -- leaves its passages, and their embeddings, alone.
    content_sha256 TEXT NOT NULL CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
    -- Whose record it came from: for the person filter and for citing who said it. Never a limit
    -- on who reads it; every member reads everything indexed (docs/knowledge.md, Who sees what).
    created_by UUID NOT NULL REFERENCES users (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT knowledge_documents_one_source CHECK (num_nonnulls(timeline_record_id) = 1)
);

SELECT diesel_manage_updated_at('knowledge_documents');

-- A document's text in order. A child of its document, so it inherits its creator and goes with
-- it.
CREATE TABLE knowledge_passages (
    document_id UUID NOT NULL REFERENCES knowledge_documents (id) ON DELETE CASCADE,
    -- Its place in the document, from 0. Indexing a document again rewrites its passages in place
    -- by position, so a passage whose text did not change keeps its embedding.
    position INTEGER NOT NULL CHECK (position >= 0),
    content TEXT NOT NULL CHECK (char_length(content) BETWEEN 1 AND 20000),
    -- Exact words: names, ticket keys, error strings. Postgres derives it, so it never drifts from
    -- the text. English stems words and drops stop words, so a question asked in a sentence still
    -- matches, while a key such as WAY-123 or ELYSIUM_PUBLIC_URL stays a phrase of its exact
    -- tokens. Searches must parse their query with the same configuration.
    search_vector TSVECTOR NOT NULL GENERATED ALWAYS AS (to_tsvector('english', content)) STORED,
    -- Meaning, from the local embedding model; NULL until it has embedded the passage. 768
    -- dimensions, the size of nomic-embed-text-v1.5, the model the embedding service is to run
    -- (docs/knowledge.md, Search). HNSW needs the size fixed in the type, so another size is a
    -- migration that re-embeds everything.
    embedding vector(768),
    -- The model, at its pinned revision, that made the embedding, so changing the model re-embeds
    -- what the old one made.
    embedding_model TEXT CHECK (char_length(embedding_model) BETWEEN 1 AND 200),

    PRIMARY KEY (document_id, position),
    CONSTRAINT knowledge_passages_embedded_by_a_model CHECK (
        (embedding IS NULL) = (embedding_model IS NULL)
    )
);

-- Full-text matches.
CREATE INDEX knowledge_passages_search_vector ON knowledge_passages USING gin (search_vector);

-- Nearest neighbours by cosine distance, the measure the model is trained for. Passages not yet
-- embedded are left out of it.
CREATE INDEX knowledge_passages_embedding ON knowledge_passages
    USING hnsw (embedding vector_cosine_ops);

-- What is still waiting for the embedding model.
CREATE INDEX knowledge_passages_unembedded ON knowledge_passages (document_id, position)
    WHERE embedding IS NULL;
